type ListParticipantsByConversationIDsRow struct {
	ConversationID pgtype.UUID `json:"conversation_id"`
	UserID         pgtype.UUID `json:"user_id"`
	Name           string      `json:"name"`
	Email          string      `json:"email"`
}

func (q *Queries) ListParticipantsByConversationIDs(ctx context.Context, conversationIds []pgtype.UUID) ([]ListParticipantsByConversationIDsRow, error) {
	rows, err := q.db.Query(ctx, listParticipantsByConversationIDs, conversationIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListParticipantsByConversationIDsRow{}
	for rows.Next() {
		var i ListParticipantsByConversationIDsRow
		if err := rows.Scan(
			&i.ConversationID,
			&i.UserID,
			&i.Name,
			&i.Email,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

